"""Strict declared source inverses for a conditional combined candidate.

These functions are for structural assertions only. Behavioral fixtures continue
to load the actual runtime. Missing/duplicated/changed fragments fail assertions;
there is no fallback, skip, fake geometry or identity stand-in.
"""
import ast
import hashlib
import json
from pathlib import Path

INVERSES=Path(__file__).resolve().parent/'fixtures/candidate_motion_inverses.json'
INVERSES_SHA='4e84adfe65911bcf62aec4cf0288a320219ce0548f55c401e4ad04e34c5b8505'


def _restore(source,layers):
    source = restore_raw_contacts_source(source)
    assert hashlib.sha256(INVERSES.read_bytes()).hexdigest()==INVERSES_SHA
    declared=json.loads(INVERSES.read_text())['layers']
    for name in layers:
        for item in reversed(declared[name]['replacements']):
            assert source.count(item['after'])==item['count'],(name,item['after'][:100])
            source=source.replace(item['after'],item['before'])
    return source


def restore_to_r51_source(source):
    return _restore(source,('nominal_torso','tool_node','velocity','arm_timing'))


def restore_motion_source(source):
    # Leave tool ownership present for its separate exact constructor inverse.
    return _restore(source,('nominal_torso','velocity','arm_timing'))


def without_torso_tool(source):
    # Keep timing/admission fully active for their behavioral/source checks.
    return _restore(source,('nominal_torso','tool_node'))


def original_send_method(source):
    root=ast.parse(restore_to_r51_source(source))
    owner=next(n for n in root.body if isinstance(n,ast.ClassDef) and n.name=='ManipulationNode')
    return next(n for n in owner.body if isinstance(n,ast.FunctionDef) and n.name=='_send_retained_arm_trajectory')


def restore_raw_contacts_source(source):
    """Remove only the six exact reviewed R52 raw-contact plumbing changes."""
    path = Path(__file__).resolve().parent/'fixtures/raw_contacts_node_inverse.json'
    source = restore_extended_arm_speed_source(source)
    data = path.read_bytes()
    assert hashlib.sha256(data).hexdigest() == 'bcb31f96715a76d4d6b2f6647456712c718e20dfcb797ee94afae1e19e17bda5'
    for item in reversed(json.loads(data)):
        assert source.count(item['new']) == 1, item['new'][:100]
        source = source.replace(item['new'], item['old'])
    assert hashlib.sha256(source.encode()).hexdigest() == '06bef5efb58b73301aced8e942a1df5528a931a3d2ce46e74d307fa29a5810bf'
    return source


def restore_extended_arm_speed_source(source):
    """Restore only the two exact supported-range fragments before older inverses."""
    source = restore_preopen_stationary_source(source)
    for current, parent in [('float(duration) / 2.5 <= command_duration', 'float(duration) / 1.25 <= command_duration'), ('the 1.0 to 2.5 speed range', 'the 1.0 to 1.25 speed range')]:
        assert source.count(current) == 1, current
        source = source.replace(current, parent)
    assert hashlib.sha256(source.encode()).hexdigest() == '14df13cfb6d80574b3a5a292b2f422a977f343e677ab9f17a986bbc0a3f71366'
    return source


def restore_preopen_stationary_source(source):
    """Remove exactly the three declared opt-in additions, then require all R54 bytes."""
    source = restore_preopen_speed_source(source)
    path = Path(__file__).resolve().parent/'fixtures/preopen_stationary_inverse.json'
    data = path.read_bytes()
    assert hashlib.sha256(data).hexdigest() == '6991ec90dc749278d75a81ee645576db7f62acc68253346fe90316c5527fcf3d'
    record = json.loads(data)
    for insertion in record['insertions']:
        assert source.count(insertion) == 1, insertion[:100]
        source = source.replace(insertion, '', 1)
    assert hashlib.sha256(source.encode()).hexdigest() == record['parent_node_sha256']
    return source


def restore_preopen_speed_source(source):
    """Restore only the two 3.0-range fragments to the passed pre-open node."""
    source = restore_stock_close_lifecycle_source(source)
    for current, parent in [('float(duration) / 3.0 <= command_duration', 'float(duration) / 2.5 <= command_duration'), ('the 1.0 to 3.0 speed range', 'the 1.0 to 2.5 speed range')]:
        assert source.count(current) == 1, current
        source = source.replace(current, parent)
    assert hashlib.sha256(source.encode()).hexdigest() == '12aa9393565e35c2a8d6bb8981b9420275dd0f400ed6a80857aa60e216dc36f9'
    return source


def restore_preopen_speed_timing_bytes(source):
    """Require exact previous timing helper after the two declared cap changes."""
    for current, parent in [(b'1.0 <= scale <= 3.0', b'1.0 <= scale <= 2.5'), (b'within [1.0, 3.0]', b'within [1.0, 2.5]')]:
        assert source.count(current) == 1, current
        source = source.replace(current, parent)
    assert hashlib.sha256(source).hexdigest() == '27956e91b78d20288fc750eb8064f7a747c23f2df181b84d0380c3134ae928e9'
    return source


def restore_stock_close_lifecycle_source(source):
    """Remove only stock publication's proof invalidation, then require all R55 bytes."""
    source = restore_withdrawal_lift_ceiling_bytes(source.encode(), 'node').decode()
    path = Path(__file__).resolve().parent/'fixtures/stock_close_lifecycle_inverse.json'
    data = path.read_bytes()
    assert hashlib.sha256(data).hexdigest() == 'cef5026022ee4961529f9ad00fb17198a68918312dff0d6d290fe7184af924bf'
    record = json.loads(data)['node_inverse']
    assert source.count(record['after']) == 1
    source = source.replace(record['after'], record['before'], 1)
    assert hashlib.sha256(source.encode()).hexdigest() == record['parent_sha256']
    return source


def restore_preopen_timing_source(source):
    """Restore only the declared timing/atomic-retention changes to exact R56."""
    data=(Path(__file__).resolve().parent/'fixtures/preopen_timing_inverse.json').read_bytes()
    assert hashlib.sha256(data).hexdigest()=='c1a1b72a95c809df888c3b5d1775f2b43bd1012d1893a15f0ae93be88f948242'
    record=json.loads(data)
    assert hashlib.sha256(source.encode()).hexdigest()==record['candidate_sha256']
    for item in record['inverses_in_reverse_order']:
        assert source.count(item['after'])==1
        source=source.replace(item['after'],item['before'],1)
    assert hashlib.sha256(source.encode()).hexdigest()==record['parent_sha256']
    return source


def restore_withdrawal_lift_ceiling_bytes(source, kind):
    """Strictly remove the three reviewed 8 mm ceiling changes only."""
    if kind == 'node':
        source = restore_withdrawal_speed_bytes(source)
    else:
        source = restore_withdrawal_twenty_mm_ceiling_bytes(source, kind)
    path = Path(__file__).resolve().parent/'fixtures/withdrawal_lift_cap_inverse.json'
    data = path.read_bytes()
    assert hashlib.sha256(data).hexdigest() == 'e3267b418562e16c738f6193191da775e01af6b95ba9e08fac4904175f5f37fb'
    record = json.loads(data)[kind]
    assert hashlib.sha256(source).hexdigest() == record['candidate_sha256']
    for item in reversed(record['replacements']):
        current, parent = item['new'].encode(), item['old'].encode()
        assert source.count(current) == item['count']
        source = source.replace(current, parent)
    assert hashlib.sha256(source).hexdigest() == record['parent_sha256']
    return source


