def restore_current_extensions(source, filename="manipulation_node.py"):
    binary = isinstance(source, bytes)
    text = source.decode() if binary else source
    for current, parent in reversed(_CURRENT_EXTENSIONS.get(filename, ())):
        assert text.count(current) == 1, (filename, current[:90])
        text = text.replace(current, parent, 1)
    return text.encode() if binary else text

